        #ifdef DEBUG
        //if (start_particlep->life_remaining + t > 0.0F)
          //debug_print("particle %s dies!!",filename.c_str());
        #endif

        // 'deallocate' particles at beginning that are dead.
        ++start_particle;
        if( start_particle>=max_particles )
          start_particle=0;
      }
      else
      {
        if(do_bsp)
